def HK(self, X):
    M = ( 1 / ( 1 + torch.exp(-( self.thres - torch.sum(X, dim=1).abs() )) ) ).reshape(X.shape[0], 1)
    K = torch.exp( - torch.cdist(X, X, p=0) / X.shape[1] * self.gamma )
    return M * K * M.t()

